def test_unsupported_native_populations_reject_before_payload(code, operation):
    """Fixed-slot exhaustion never treats PMF or PDF as resolved counts."""
    from particula.gpu.kernels import exhaustion as module

    class Tagged:
        distribution_kind = code

        def __getattr__(self, name):
            pytest.fail(f"unsupported population accessed {name}")

    with pytest.raises(ValueError, match="only particle_resolved"):
        if operation == "resampling":
            module._prepare_resampling_step_gpu(Tagged(), None, None)
        else:
            module._prepare_representative_volume_scaling_step_gpu(
                Tagged(),
                None,
                None,
                None,
                None,
                None,
                None,
            )

def test_unmigrated_consumers_reject_before_payload_access(module, name, code):
    """Every direct/prepared route protects the newly transferable tag."""
    pytest.importorskip("warp")
    function = getattr(
        importlib.import_module(f"particula.gpu.kernels.{module}"), name
    )
    kwargs = {
        key: None
        for key, parameter in inspect.signature(function).parameters.items()
        if parameter.default is inspect.Parameter.empty
    }
    kwargs["particles"] = _TaggedOnly()
    kwargs["particles"].distribution_kind = code
    with pytest.raises(ValueError, match="require a migrated consumer"):
        function(**kwargs)

